--- index.html
+++ index.html
@@ -39,4 +39,38 @@
 <div class="modal-footer"><button class="primary-btn" data-close="settingsModal">Back to the glade</button></div></section></div>
 <div class="modal-backdrop" id="classModal"><section class="modal"><div class="modal-head"><div><div class="eyebrow">Choose your calling</div><h2>Walk a different path</h2><p>Your skills and combat style change with your calling.</p></div><button class="close-btn" data-close="classModal" aria-label="Close">×</button></div><div class="class-grid" id="classGrid"></div><div class="modal-footer"><button class="primary-btn" id="confirmClass">Take this path</button></div></section></div>
 </main>
 <script>
+(()=>{'use strict';
+const canvas=document.getElementById('world'),ctx=canvas.getContext('2d');
+const $=id=>document.getElementById(id); const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
+const paths=[
+ {name:'Warden',icon:'🛡️',desc:'A steadfast blade, rooted in nature and hard to bring down.',role:'Frontline · Resilience',skills:[['🌿','Thorn Rush',18,24,3.8,'#9bdb91'],['🛡️','Bramble Guard',0,0,9,'#d7c27c'],['🌙','Mooncleave',26,38,7,'#e4d28d'],['✨','Verdant Pulse',22,28,8,'#99e3bb']]},
+ {name:'Arcanist',icon:'🔮',desc:'A scholar of wild magic who turns focus into devastating spells.',role:'Spellcraft · Burst',skills:[['✦','Starfall',24,35,4.2,'#b3a5ff'],['❄','Frostbind',20,24,6.5,'#8bd9ed'],['☄','Comet Arc',32,49,9,'#f5ad7f'],['◉','Aether Well',18,22,7.5,'#ce9bee']]},
+ {name:'Ranger',icon:'🏹',desc:'A quick-footed scout who strikes true from the edge of danger.',role:'Ranged · Precision',skills:[['➶','Quickshot',13,19,2.4,'#e9c47e'],['🪶','Gale Volley',23,30,5,'#a8d7a4'],['🦊','Foxstep',0,0,7,'#e8a68f'],['☼','Sunpiercer',31,43,8,'#f3d37e']]}
+];
+let W=0,H=0,dpr=1,last=0,now=0,toastTimer,logTimer=0,selectedClass=0,previewClass=0;
+const saved=(()=>{try{return JSON.parse(localStorage.getItem('mythvale-settings')||'{}')}catch{return {}}})();
+const settings={speed:saved.speed||1,attackSpeed:saved.attackSpeed||1,skillAnimations:saved.skillAnimations!==false,damageNumbers:saved.damageNumbers!==false,reducedShake:!!saved.reducedShake,sound:false};
+const player={x:0,y:0,r:17,hp:100,maxHp:100,mp:80,maxMp:80,xp:38,level:4,facing:1,attackCd:0,attackAnim:0,guard:0,potions:3,dead:false};
+let skills=[],mobs=[],particles=[],texts=[],kills=0,questTarget=6,shake=0;
+const keys={};
+function resize(){dpr=Math.min(devicePixelRatio||1,2);const rect=canvas.getBoundingClientRect();W=rect.width;H=rect.height;canvas.width=Math.floor(W*dpr);canvas.height=Math.floor(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!player.x){player.x=W*.49;player.y=H*.55;spawnMobs()}}
+window.addEventListener('resize',resize);
+function activePath(){return paths[selectedClass]}
+function buildSkills(){skills=activePath().skills.map((s,i)=>({name:s[1],icon:s[0],cost:s[2],damage:s[3],baseCd:s[4],color:s[5],cd:0}));const bar=$('skillBar');bar.innerHTML='';skills.forEach((s,i)=>{const b=document.createElement('button');b.className='skill-btn';b.dataset.action='skill'+i;b.setAttribute('aria-label',`${s.name}, skill ${i+1}`);b.innerHTML=`<span class="hotkey">${i+1}</span><span class="glyph">${s.icon}</span><span class="skill-name">${s.name}</span><span class="cost">${s.cost||'—'}</span><span class="cooldown"></span>`;bar.appendChild(b)})}
+function spawnMobs(){mobs=[];for(let i=0;i<8;i++){const a=Math.PI*2*i/8+Math.random()*.5,d=Math.min(W,H)*(.25+Math.random()*.16);mobs.push(makeMob(player.x+Math.cos(a)*d,player.y+Math.sin(a)*d))}}
+function makeMob(x,y){return {x:clamp(x,35,W-35),y:clamp(y,100,H-105),r:15+Math.random()*3,hp:52,maxHp:52,hit:0,attack:0,wobble:Math.random()*7,dead:false,respawn:0}}
+function saveSettings(){try{localStorage.setItem('mythvale-settings',JSON.stringify(settings))}catch{}}
+function toast(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
+function log(msg){const line=document.createElement('div');line.className='log-line';line.innerHTML=msg;$('combatLog').prepend(line);while($('combatLog').children.length>4)$('combatLog').lastChild.remove();setTimeout(()=>line.remove(),4100)}
+function syncHud(){ $('playerClass').textContent=activePath().name;$('levelText').textContent=`LV. ${String(player.level).padStart(2,'0')}`;$('hpText').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;$('mpText').textContent=`${Math.ceil(player.mp)} / ${player.maxMp}`;$('hpBar').style.width=`${player.hp/player.maxHp*100}%`;$('mpBar').style.width=`${player.mp/player.maxMp*100}%`;$('xpBar').style.width=`${player.xp}%`;$('potionCount').textContent=player.potions;$('questCount').textContent=`${kills % questTarget} / ${questTarget}`;$('questBar').style.width=`${kills%questTarget/questTarget*100}%`}
+function nearest(){let best=null,dist=Infinity;for(const m of mobs){if(m.dead)continue;const d=Math.hypot(m.x-player.x,m.y-player.y);if(d<dist){dist=d;best=m}}return best?{mob:best,dist}:null}
+function addText(x,y,text,color='#fff0b0'){if(settings.damageNumbers)texts.push({x,y,text,color,life:.85})}
+function burst(x,y,color,count=9){for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,v=25+Math.random()*100;particles.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:.25+Math.random()*.5,max:.75,color,r:1.5+Math.random()*3})}}
+function doAttack(index=-1){if(player.dead)return;const basic=index<0,sk=basic?null:skills[index];if(sk&&sk.cd>0)return;if(sk&&player.mp<sk.cost){toast('Not enough focus');return}if(basic&&player.attackCd>0)return;
+const target=nearest(),range=basic?88:(selectedClass===1?260:220);if(!target||target.dist>range){if(!basic)toast('No wildling in range');return}
+if(sk){player.mp-=sk.cost;sk.cd=sk.baseCd/settings.attackSpeed} else player.attackCd=.64/settings.attackSpeed;
+const m=target.mob;player.facing=m.x<player.x?-1:1;const damage=sk?sk.damage:15+Math.round(Math.random()*7);m.hp-=damage;m.hit=.19;player.attackAnim=settings.skillAnimations?.23:.07;
+if(sk){burst(m.x,m.y,sk.color,settings.skillAnimations?13:4);if(sk.name==='Bramble Guard'||sk.name==='Foxstep'){player.guard=2.2;player.hp=Math.min(player.maxHp,player.hp+12);addText(player.x,player.y-28,'+12','#b9edaa')}if(sk.name==='Verdant Pulse'||sk.name==='Aether Well'){player.hp=Math.min(player.maxHp,player.hp+7)}}else burst(m.x,m.y,'#f0c46d',5);
+addText(m.x,m.y-m.r-8,damage,sk?sk.color:'#ffe2a1');if(!settings.reducedShake)shake=sk?5:2;
+if(m.hp<=0){m.dead=true;m.respawn=3.4;kills++;player.xp+=12;log(`<strong>${m.name||'Mossling'}</strong> scattered · +12 XP`);if(kills%questTarget===0){toast('Field journal updated · '+questTarget+' wildlings cleared');player.xp+=16}if(player.xp>=100){player.xp-=100;player.level++;player.maxHp+=12;player.maxMp+=8;player.hp=player.maxHp;player.mp=player.maxMp;$('levelup').classList.add('show');setTimeout(()=>$('levelup').classList.remove('show'),2100);log('<strong>Level up!</strong> You feel more capable.')}}syncHud()}

