if(player.xp>=100){player.xp-=100;player.level++;player.maxHp+=12;player.maxMp+=8;player.hp=player.maxHp;player.mp=player.maxMp;$('levelup').classList.add('show');setTimeout(()=>$('levelup').classList.remove('show'),2100);log('<strong>Level up!</strong> You feel more capable.')}}syncHud()}
function rr(x,y,w,h,r){ctx.beginPath();ctx.roundRect(x,y,w,h,r)}
function drawGround(){
 const g=ctx.createLinearGradient(0,0,W,H);g.addColorStop(0,'#354538');g.addColorStop(.46,'#293b31');g.addColorStop(1,'#1b3029');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // Soft patches of moss and scattered grass flecks.
 for(let i=0;i<34;i++){const x=((i*173+37)%Math.max(W,1)),y=((i*281+71)%Math.max(H,1));ctx.fillStyle=i%3?'rgba(152,178,112,.035)':'rgba(190,164,101,.035)';ctx.beginPath();ctx.ellipse(x,y,28+(i*19)%72,13+(i*11)%34,i*.4,0,Math.PI*2);ctx.fill()}
 // Worn stone path through the glade.
 ctx.save();ctx.globalAlpha=.22;ctx.strokeStyle='#c1b68c';ctx.lineWidth=86;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-50,H*.69);ctx.bezierCurveTo(W*.24,H*.58,W*.36,H*.71,W*.56,H*.59);ctx.bezierCurveTo(W*.76,H*.46,W*.83,H*.55,W+80,H*.36);ctx.stroke();ctx.globalAlpha=.18;ctx.strokeStyle='#dfd0a6';ctx.lineWidth=2;ctx.setLineDash([3,16]);ctx.stroke();ctx.restore();
 // Rune stones in the ancient ring.
 const cx=W*.76,cy=H*.49;ctx.save();ctx.strokeStyle='rgba(200,191,143,.2)';ctx.lineWidth=2;ctx.setLineDash([5,12]);ctx.beginPath();ctx.ellipse(cx,cy,75,47,-.25,0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);
 for(let i=0;i<7;i++){const a=i*Math.PI*2/7;const x=cx+Math.cos(a)*76,y=cy+Math.sin(a)*48;ctx.fillStyle='#66745c';ctx.beginPath();ctx.ellipse(x,y,12,8,a,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#8c9670';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='rgba(191,203,136,.5)';ctx.fillRect(x-1,y-2,2,4)}ctx.restore();
 // Fern silhouettes around the edge.
 for(let i=0;i<29;i++){const x=(i*197+19)%Math.max(W,1),y=i%2?((i*97+21)%Math.max(H*.23,1)):H-((i*103+17)%Math.max(H*.2,1));drawFern(x,y,(i%3)*.35)}
 for(let i=0;i<19;i++){const x=(i*211+43)%Math.max(W,1),y=(i*149+33)%Math.max(H,1);if(Math.hypot(x-player.x,y-player.y)<100)continue;if(i%4===0)drawCrystal(x,y);else if(i%3===0)drawRock(x,y);else drawFlower(x,y)}
}
function drawFern(x,y,r){ctx.save();ctx.translate(x,y);ctx.rotate(r);ctx.strokeStyle='rgba(13,29,21,.58)';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(0,11);ctx.quadraticCurveTo(8,-5,2,-30);ctx.stroke();for(let i=0;i<5;i++){const yy=-4-i*5;ctx.fillStyle=i%2?'rgba(83,122,74,.54)':'rgba(102,143,82,.48)';ctx.beginPath();ctx.ellipse(-5,yy,7,2.4,-.55,0,Math.PI*2);ctx.ellipse(6,yy-2,7,2.4,.55,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawRock(x,y){ctx.fillStyle='#111d17';ctx.beginPath();ctx.ellipse(x,y+5,13,6,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#657565';ctx.beginPath();ctx.moveTo(x-12,y+2);ctx.lineTo(x-7,y-7);ctx.lineTo(x+2,y-10);ctx.lineTo(x+12,y-3);ctx.lineTo(x+9,y+4);ctx.closePath();ctx.fill();ctx.fillStyle='#91a080';ctx.fillRect(x-5,y-5,3,2)}
function drawCrystal(x,y){ctx.save();ctx.shadowBlur=14;ctx.shadowColor='#7dc6b2';ctx.fillStyle='#63a895';ctx.beginPath();ctx.moveTo(x,y-14);ctx.lineTo(x+7,y-2);ctx.lineTo(x+4,y+7);ctx.lineTo(x-5,y+5);ctx.lineTo(x-7,y-2);ctx.closePath();ctx.fill();ctx.fillStyle='#a0e3c9';ctx.beginPath();ctx.moveTo(x,y-14);ctx.lineTo(x+1,y+3);ctx.lineTo(x-4,y+2);ctx.closePath();ctx.fill();ctx.restore()}
function drawFlower(x,y){ctx.fillStyle='#14251b';ctx.beginPath();ctx.ellipse(x,y+4,7,3,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#d5c87d';ctx.beginPath();ctx.arc(x,y,2.3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eee2ad';for(let i=0;i<4;i++){const a=i*Math.PI/2;ctx.beginPath();ctx.arc(x+Math.cos(a)*3,y+Math.sin(a)*3,1.7,0,Math.PI*2);ctx.fill()}}
function drawMob(m){if(m.dead)return;const bob=Math.sin(now*3+m.wobble)*1.5;ctx.save();ctx.translate(m.x,m.y+bob);ctx.fillStyle='#101a13a8';ctx.beginPath();ctx.ellipse(0,13,19,7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=m.hit?'#e7d29a':'#73966a';ctx.beginPath();ctx.ellipse(0,0,16,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=m.hit?'#f1e3be':'#99b67c';ctx.beginPath();ctx.ellipse(-2,-4,10,7,-.25,Math.PI,Math.PI*2);ctx.fill();ctx.fillStyle='#52704e';ctx.beginPath();ctx.moveTo(-6,-11);ctx.quadraticCurveTo(-8,-21,-1,-17);ctx.quadraticCurveTo(5,-16,3,-10);ctx.fill();ctx.fillStyle='#263a2e';ctx.beginPath();ctx.arc(-5,1,1.6,0,Math.PI*2);ctx.arc(4,1,1.6,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#40563c';ctx.lineWidth=1.2;ctx.beginPath();ctx.arc(0,4,3,.2,Math.PI-.2);ctx.stroke();ctx.restore();
 if(m.hp<m.maxHp){ctx.fillStyle='#101810';rr(m.x-16,m.y-23,32,4,2);ctx.fill();ctx.fillStyle='#d18c66';rr(m.x-15,m.y-22,30*Math.max(0,m.hp/m.maxHp),2,1);ctx.fill()}}
function drawHero(){const a=player.attackAnim>0?Math.sin(player.attackAnim*16)*3:0;ctx.save();ctx.translate(player.x+a,player.y);ctx.fillStyle='#101710aa';ctx.beginPath();ctx.ellipse(0,14,20,8,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#78624b';ctx.beginPath();ctx.ellipse(0,4,13,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9fb875';ctx.beginPath();ctx.moveTo(-11,-1);ctx.quadraticCurveTo(-15,8,-20,18);ctx.quadraticCurveTo(-6,13,0,13);ctx.quadraticCurveTo(11,17,20,11);ctx.quadraticCurveTo(12,4,11,-1);ctx.closePath();ctx.fill();ctx.fillStyle='#e2c89b';ctx.beginPath();ctx.arc(0,-6,9,0,Math.PI*2);ctx.fill();ctx.fillStyle='#574637';ctx.beginPath();ctx.arc(0,-9,9,Math.PI,Math.PI*2);ctx.lineTo(7,-4);ctx.quadraticCurveTo(0,-9,-8,-4);ctx.closePath();ctx.fill();ctx.fillStyle='#38352b';ctx.beginPath();ctx.arc(player.facing*3,-5,1.1,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#d1d9bf';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(player.facing*9,-3);ctx.lineTo(player.facing*17,-16);ctx.stroke();ctx.strokeStyle='#bd9c61';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(player.facing*12,-8);ctx.lineTo(player.facing*7,-5);ctx.stroke();if(player.guard>0){ctx.strokeStyle='rgba(176,229,173,.65)';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,25,now,now+4.4);ctx.stroke()}ctx.restore();ctx.fillStyle='#f0e9ce';ctx.font='10px sans-serif';ctx.textAlign='center';ctx.fillText('Aerin',player.x,player.y-28)}

